import { expect, expectStatus, test } from "../../fixtures";

test("A vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor submitted for review, so its status is in_review
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview({ as: "member" });

  // Act: the member changes the vendor's contact email
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert: the edit is refused, and the stored contact email is unchanged
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");
  const after = await expectStatus(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(after.status).toBe("in_review");
  expect(after.contact_email).toBe("ops@vendor.example");
});
